"""Dokkai N4 v2 — paket 11–15. Susunan: 4 短文 + 中文 (3 soal) + 情報検索 (2 soal) = 9."""
T, C, J = "Teks pendek (短文)", "Teks menengah (中文)", "Mencari informasi (情報検索)"


def tbl(head, rows):
    h = "".join(f"<th>{x}</th>" for x in head)
    b = "".join("<tr>" + "".join(f"<td>{x}</td>" for x in r) + "</tr>" for r in rows)
    return f"<table class='jx-table'><tr>{h}</tr>{b}</table>"


